package com.movieworth.api.ingestion;
import com.movieworth.api.movie.*;import com.movieworth.api.boxoffice.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Component public class BoxOfficeScheduler{private final BoxOfficeFeedClient feed;private final MovieRepository movies;private final CollectionRepository snapshots;private final boolean enabled;public BoxOfficeScheduler(BoxOfficeFeedClient f,MovieRepository m,CollectionRepository s,@Value("${movieworth.box-office.enabled:false}")boolean e){feed=f;movies=m;snapshots=s;enabled=e;}
@Scheduled(cron="${movieworth.box-office.cron:0 0 * * * *}")public void hourly(){if(!enabled)return;try{persist(feed.fetchDaily());}catch(Exception ex){System.err.println("Box-office ingest failed: "+ex.getMessage());}}
@Transactional public void persist(List<BoxOfficeFeedClient.FeedRecord> rows){for(var r:rows){movies.findByTmdbId(r.tmdbId()).ifPresent(movie->{CollectionSnapshot s=snapshots.findByMovieIdAndCollectionDateAndSource(movie.getId(),r.date(),"AUTHORIZED_FEED").orElseGet(CollectionSnapshot::new);s.setMovie(movie);s.setCollectionDate(r.date());s.setIndiaNetCr(r.indiaNetCr());s.setIndiaGrossCr(r.indiaGrossCr());s.setOverseasGrossCr(r.overseasCr());s.setWorldwideGrossCr(r.worldwideCr());s.setSource("AUTHORIZED_FEED");s.setSourceUrl(r.sourceUrl());snapshots.save(s);});}}}